#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {	// your code goes here	int n;	cin >> n;		vector<int>vec(n);	for(auto &x : vec){	    cin >> x;	}			vector<int>prefix(n + 1);	for(int i = 1 ; i <= n ; i ++){	    prefix[i] = prefix[i - 1] + vec[i - 1];	}		int qi;	cin >> qi;	vector<int>query(qi);	for(auto &x : query){	    cin >> x;	}			for(auto it : query){	    int idx = lower_bound(prefix.begin() + 1, prefix.end(), it) - prefix.begin();	    	    cout << idx << endl;	} }